        focus_pane_up = [
          "prefix+k"
          "alt+k"
        ];

        swap_pane_left = [
          "prefix+shift+h"
          "alt+shift+h"
        ];
        swap_pane_down = [
          "prefix+shift+j"
          "alt+shift+j"
        ];
        swap_pane_up = [
          "prefix+shift+k"
          "alt+shift+k"
        ];
        swap_pane_right = [
          "prefix+shift+l"
          "alt+shift+l"
        ];

        split_vertical = [
          "prefix+v"
          "alt+n"
        ];
        split_horizontal = [
          "prefix+minus"
          "alt+d"
        ];
        new_tab = [
          "prefix+c"
          "alt+t"
        ];
        copy_mode = [
          "prefix+["
          "prefix+s"
        ];

        settings = "prefix+comma";
        command = [
          {
            key = "alt+l";
            type = "plugin_action";
            command = "herdr-focus-or-tab.next";
            description = "focus next pane or tab";
          }
          {
            key = "alt+h";
            type = "plugin_action";
            command = "herdr-focus-or-tab.previous";
            description = "focus previous pane or tab";
          }
          {
            key = "prefix+t";
            type = "plugin_action";
            command = "herdr-navigator.open";
            description = "jump to anything";
          }
